/* ---------- builder state: a mockup is a project of one or more linked screens ---------- */
const FR={desktop:[1280,800,'Desktop'],tablet:[834,1112,'Tablet'],mobile:[390,844,'Mobile']};
function uid(){return Math.random().toString(36).slice(2,9)}
function blankScreen(name,frame){return {sid:uid(),name:name||'Screen 1',frame:FR[frame]?frame:'desktop',notes:'',els:[],guides:[],layout:''}}
// Accepts saved projects, files and older single-screen mockups ({frame, notes, els}).
function toProject(d){d=JSON.parse(JSON.stringify(d||{}));importDefs(d.elements);const raw=d.screens?.length?d.screens:[{name:'Screen 1',frame:d.frame,notes:d.notes,els:d.els}];const screens=raw.map(s=>({...blankScreen(),...s,frame:FR[s.frame]?s.frame:'desktop',notes:s.notes||'',els:(s.els||[]).filter(ensureType).map(e=>({...e,uid:e.uid||uid()})),...(s.base?{base:{...s.base,els:(s.base.els||[]).filter(ensureType)}}:{}),guides:s.guides||[],layout:s.layout||''}));return {id:d.id||null,example:!!d.example,name:d.name||'Untitled mockup',style:d.style||null,screens,cur:screens.some(s=>s.sid===d.cur)?d.cur:screens[0].sid,savedSig:d.savedSig??null}}
