let P,M;
function useScreen(sid){P.cur=P.screens.some(s=>s.sid===sid)?sid:P.screens[0].sid;M=P.screens.find(s=>s.sid===P.cur)}
function loadProject(d){P=toProject(d);useScreen(P.cur)}
loadProject(LS.get('uifg.draft',null)||EXAMPLE);
let sel=null,snap=LS.get('uifg.snap',true),undoS=[],redoS=[],scale=1,flowOn=false,conOn=false,con=null,flowZ=LS.get('uifg.flowZ',1);
const hash=s=>{let h=5381;for(let i=0;i<s.length;i++)h=(h*33^s.charCodeAt(i))|0;return h};
const sig=()=>hash(JSON.stringify([P.name,P.screens,P.style||null]));
const scrName=sid=>sid==='@back'?'Back':P.screens.find(s=>s.sid===sid)?.name;
const elName=e=>{const d=EM[e.type];return e.t&&!IP[e.t]?`${d.n} “${short(e.t,24)}”`:d.n};
const isMob=(s=M)=>FR[s.frame][0]<600;
function saveDraft(){clearTimeout(saveDraft.t);saveDraft.t=setTimeout(()=>{if(LS.set('uifg.draft',P)&&storeFull){storeFull=false;drawStoreBar()}drawStatus()},300)}
function drawStatus(){const s=$('#dirty');const ch=P.id&&P.savedSig!==sig();s.textContent=P.example?'Example':!P.id?'Not saved yet':ch?'Unsaved changes':'Saved';s.classList.toggle('on',!P.example&&(!P.id||!!ch))}
function pushUndo(){undoS.push(JSON.stringify(P));if(undoS.length>80)undoS.shift();redoS=[]}
function restore(s){P=JSON.parse(s);useScreen(P.cur);clearSel();drawAll();pushLib();drawSketch()}
function undo(){if(!undoS.length)return;redoS.push(JSON.stringify(P));restore(undoS.pop())}
function redo(){if(!redoS.length)return;undoS.push(JSON.stringify(P));restore(redoS.pop())}
const G=v=>snap?Math.round(v/8)*8:Math.round(v);

