const dropTarget=(ev,sid)=>{const n=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.fnode,.fnew');return n&&n.dataset.sid!==sid?n:null};
function fcMove(ev){if(!fc)return;if(!fc.moved&&Math.hypot(ev.clientX-fc.sx,ev.clientY-fc.sy)<6)return;fc.moved=true;const c=$('.flowc').getBoundingClientRect(),r=fc.fe.getBoundingClientRect();let t=$('#ftmp');if(!t){$('#fa').insertAdjacentHTML('beforeend','<path id="ftmp" fill="none" style="stroke:var(--accent)" stroke-width="2" stroke-dasharray="6 4" marker-end="url(#fah)"/>');t=$('#ftmp')}t.setAttribute('d',`M${r.left+r.width/2-c.left} ${r.top+r.height/2-c.top}L${ev.clientX-c.left} ${ev.clientY-c.top}`);const tg=dropTarget(ev,fc.sid);document.querySelectorAll('#flow .tgt').forEach(n=>n!==tg&&n.classList.remove('tgt'));tg?.classList.add('tgt')}
