/* keyboard */
addEventListener('keydown',ev=>{if($('#vBld').hidden||document.getElementById('ovl'))return;const tg=ev.target;const typing=tg.matches('input,textarea,select');const mod=ev.metaKey||ev.ctrlKey;const k=ev.key.toLowerCase();if(mod&&k==='\\'){ev.preventDefault();setInsp(!inspOn);return}if(mod&&k==='s'){ev.preventDefault();saveProject(ev.shiftKey);return}if(mod&&k==='z'&&!typing){ev.preventDefault();ev.shiftKey?redo():undo();return}if(typing)return;
 if(flowOn){if(ev.key==='Escape'&&conOn){if(con)con=null;else conOn=false;drawFlow()}return}
 if(ev.key==='Escape'){clearSel();drawCanvas();drawInsp();return}if(mod&&k==='a'){ev.preventDefault();setSel(M.els.map(e=>e.uid));return}if(mod&&k==='v'){ev.preventDefault();paste();return}if(mod&&(k==='c'||k==='x')){if(selEls().length){ev.preventDefault();copySel(k==='x')}return}
 const S=selEls();if(!S.length)return;if(ev.key==='Delete'||ev.key==='Backspace'){ev.preventDefault();del()}else if(mod&&k==='d'){ev.preventDefault();dup()}else if(ev.key.startsWith('Arrow')){ev.preventDefault();if(!ev.repeat)pushUndo();const s=ev.shiftKey?8:1,e=S[0];(S.length>1?S:e.g&&!ev.altKey?M.els.filter(x=>x.g===e.g):[e]).forEach(x=>{if(ev.key==='ArrowLeft')x.x-=s;if(ev.key==='ArrowRight')x.x+=s;if(ev.key==='ArrowUp')x.y=Math.max(0,x.y-s);if(ev.key==='ArrowDown')x.y+=s;const n=$(`.el[data-uid="${x.uid}"]`);n.style.left=x.x+'px';n.style.top=x.y+'px'});syncLinked(S.length>1?S:e.g&&!ev.altKey?M.els.filter(x=>x.g===e.g):[e]);syncXYWH(e);saveDraft()}});

