/* ---------- groups: your own reusable sets of elements (a header + menu, a footer…), kept across mockups ---------- */
let groups=LS.get('uifg.groups',[]);
const selForGroup=()=>{const S=selEls();return S.length===1&&S[0].g?M.els.filter(x=>x.g===S[0].g):S};
// Fit a group saved on one frame width to another: full-width pieces stretch, right-side pieces keep their right margin, centred ones stay centred.
// Fit an x position from one frame width to another: full-width pieces stretch, right-side pieces keep their right margin, centred ones stay centred.
function fitX(x,w,sw,W){if(W===sw)return [x,w];if(x<=1&&w>=sw-2)return [0,W];if(x+w/2>sw*2/3)x=W-(sw-x);else if(x+w/2>sw/3)x=Math.round(x+(W-sw)/2);w=Math.min(w,W);return [Math.max(0,Math.min(W-w,x)),w]}
function groupBox(gr,s=M){const W=FR[s.frame][0],sw=gr.fw||W;const els=gr.els.filter(e=>EM[e.type]).map((e,i)=>{const [x,w]=fitX(e.x,e.w,sw,W);return {...e,x,w,lk:e.lk??i}});const x0=Math.min(...els.map(e=>e.x)),y0=Math.min(...els.map(e=>e.y));return {els,x0,y0,w:Math.max(...els.map(e=>e.x+e.w))-x0,h:Math.max(...els.map(e=>e.y+e.h))-y0}}
/* linked copies: every element placed from a saved group remembers the group (lg) and which piece it is (lk).
   Editing one copy updates the other copies in this mockup and the saved group; other mockups catch up when opened. */
const linked=e=>!!e?.lg&&groups.some(g=>g.id===e.lg);
const pieceOf=({uid,g,gn,lg,...r})=>r;
const copiesOf=lg=>new Set(P.screens.flatMap(s=>s.els.filter(e=>e.lg===lg).map(e=>e.g))).size;
// Make copy g on screen s match src. Positions follow a piece that wasn't just edited, so each copy keeps its own place.
function applyPieces(src,sw,s,g,skip=new Set()){const W=FR[s.frame][0];const cur=s.els.filter(e=>e.g===g);if(!cur.length)return false;const before=JSON.stringify(cur);const by=Object.fromEntries(cur.map(e=>[e.lk,e]));const ref=src.find(p=>by[p.lk]&&!skip.has(p.lk));const keep=new Set(src.map(p=>p.lk));s.els=s.els.filter(e=>e.g!==g||keep.has(e.lk));
 src.forEach(p=>{let e=by[p.lk];if(!e){if(!ref)return;e={uid:uid(),g,gn:cur[0].gn,lg:cur[0].lg,lk:p.lk};s.els.push(e)}e.type=p.type;e.t=p.t;e.h=p.h;['note','link'].forEach(k=>{if(p[k])e[k]=p[k];else delete e[k]});if(e.link&&e.link!=='@back'&&!P.screens.some(x=>x.sid===e.link))delete e.link;const [fx,fw]=fitX(p.x,p.w,sw,W);e.w=fw;if(ref&&p!==ref){const r=by[ref.lk];e.y=r.y+(p.y-ref.y);e.x=W===sw?r.x+(p.x-ref.x):fx}});
 return JSON.stringify(s.els.filter(e=>e.g===g))!==before}
const libT={};
function syncLinked(touched){const gs=new Map();touched.forEach(e=>{if(linked(e))gs.set(e.g,e.lg)});let copies=0,redraw=false;
 gs.forEach((lg,g)=>{const src=M.els.filter(x=>x.g===g);if(!src.length)return;const pieces=src.map(pieceOf),sw=FR[M.frame][0],skip=new Set(touched.filter(x=>x.g===g).map(x=>x.lk));
  P.screens.forEach(s=>new Set(s.els.filter(x=>x.lg===lg&&x.g!==g).map(x=>x.g)).forEach(g2=>{if(applyPieces(pieces,sw,s,g2,skip)){copies++;if(s===M)redraw=true}}));
  clearTimeout(libT[lg]);libT[lg]=setTimeout(()=>{const gr=groups.find(x=>x.id===lg);if(gr)putGroup({...gr,els:pieces,fw:sw,frame:M.frame,updatedAt:Date.now()})},400)});
 if(redraw)drawCanvas();return copies}
// Bring copies in the open mockup up to date with the saved groups (after opening, restoring or loading).
function pullLinked(){let n=0;groups.forEach(gr=>{const src=gr.els.map((p,i)=>({...p,lk:p.lk??i}));P.screens.forEach(s=>new Set(s.els.filter(x=>x.lg===gr.id).map(x=>x.g)).forEach(g=>{if(applyPieces(src,gr.fw||FR[s.frame][0],s,g))n++}))});return n}
// After undo/redo, make each saved group match its copy in the restored mockup.
function pushLib(){groups.forEach(gr=>{const s=[M,...P.screens].find(x=>x.els.some(e=>e.lg===gr.id));if(!s)return;const g=s.els.find(e=>e.lg===gr.id).g;const pieces=s.els.filter(e=>e.g===g).map(pieceOf);if(JSON.stringify(pieces)!==JSON.stringify(gr.els))putGroup({...gr,els:pieces,fw:FR[s.frame][0],frame:s.frame,updatedAt:Date.now()})})}
const groupInner=b=>blockInner(b.els.map(e=>[e.type,e.x-b.x0,e.y-b.y0,e.w,e.h,e.t]));
function drawGroupsBar(){const n=selForGroup().length;$('#gbar').innerHTML=`<span class="eyebrow" title="Your saved element groups">Groups</span><div class="gchips">${groups.length?groups.map(g=>`<button class="gchip" data-grp="${esc(g.id)}" title="Click: add to this screen · Shift-click: add to every screen · Drag: place it">${I('grid',12)}${esc(g.name)}<span class="k">${g.els.length}</span></button>`).join(''):'<span class="ghint">Reuse a header, menu or any set of elements on other screens: drag a box around them on the canvas, then press Save selection.</span>'}</div><button class="b sm" id="gSave" ${n?'':'disabled'} title="Save the selected elements as a reusable group">${I('plus',13)}Save selection${n?` (${n})`:''}</button>${groups.length?'<button class="b sm" id="gMan" title="Rename, delete or add a group to every screen">Manage</button>':''}`}
function saveSelAsGroup(){const S=selForGroup();if(!S.length)return toast('Select elements first: drag a box around them, or Shift-click them.');const def=S[0].gn&&S.every(e=>e.g===S[0].g)?S[0].gn:S.every(e=>e.y<160)?'Header':`Group ${groups.length+1}`;showModal('Save as group',`<p class="mlead">Saves ${S.length===1?'this element':`these ${S.length} elements`} with positions, labels, notes and links. The group appears in the second toolbar row: click it to add it to the current screen in the same spot, Shift-click to add it to every screen, or drag it into place. Groups are available in every mockup.</p><div class="fld"><label for="gName">Group name</label><input class="inp" id="gName" value="${esc(def)}"></div><div class="btnrow"><button class="b pri" id="gGo">Save group</button><button class="b" data-close>Cancel</button></div>`);const go=()=>{const name=$('#gName').value.trim()||def;closeOverlay();const id=slug(name)+'-'+uid().slice(0,4);putGroup({id,name,frame:M.frame,fw:FR[M.frame][0],els:S.map(({uid,g,gn,lg,bid,...r},i)=>({...r,lk:i})),updatedAt:Date.now()});pushUndo();const g=uid();S.forEach((e,i)=>{Object.assign(e,{g,gn:name,lg:id,lk:i})});drawAll();toast(`Saved “${name}” to Groups. Copies you add stay linked: edit one and they all update.`)};$('#gGo').onclick=go;$('#gName').onkeydown=ev=>{if(ev.key==='Enter')go()};setTimeout(()=>{$('#gName')?.focus();$('#gName')?.select()},0)}
async function putGroup(g){const i=groups.findIndex(x=>x.id===g.id);if(i<0)groups.unshift(g);else groups[i]=g;drawGroupsBar();if(db){const {id,...doc}=g;try{return await db.doc('groups/'+id).set(doc)}catch{toast('Could not save to the shared store. Saved in this browser instead.')}}LS.set('uifg.groups',groups)}
async function dropGroup(id){groups=groups.filter(x=>x.id!==id);P.screens.forEach(s=>s.els.forEach(e=>{if(e.lg===id){delete e.lg;delete e.lk}}));saveDraft();drawGroupsBar();if(db){try{return await db.doc('groups/'+id).delete()}catch{}}LS.set('uifg.groups',groups)}
function insertGroup(id,{cx,cy,all}={}){const gr=groups.find(x=>x.id===id);if(!gr)return;if(flowOn)setFlow(false);const targets=all?P.screens.filter(s=>!s.els.some(e=>e.lg===gr.id)):[M];pushUndo();P.example=false;let mine=[];targets.forEach(s=>{const b=groupBox(gr,s);const dx=s===M&&cx!=null?G(cx-b.w/2)-b.x0:0,dy=s===M&&cy!=null?G(Math.max(0,cy-b.h/2))-b.y0:0;const g=uid();const add=b.els.map(e=>{const n={...e,uid:uid(),x:e.x+dx,y:e.y+dy,g,gn:gr.name,lg:gr.id};delete n.bid;if(n.link&&n.link!=='@back'&&!P.screens.some(x=>x.sid===n.link))delete n.link;return n});s.els.push(...add);if(s===M)mine=add});setSel(mine.map(e=>e.uid));drawAll();const skipped=P.screens.length-targets.length;toast(all?`Added “${gr.name}” to ${targets.length} screen${targets.length>1?'s':''}${skipped?` (${skipped} already had it)`:''}`:`Added “${gr.name}”. Shift-click a group to add it to every screen.`)}
function manageGroups(){const m=showModal('Groups',`<p class="mlead">${db?'Saved to this page, so everyone using it sees the same groups.':'Saved in this browser and available in every mockup you open here.'} Rename a group by editing its name.</p><div class="saved" id="grpList"></div>`);const draw=()=>{$('#grpList').innerHTML=groups.length?groups.map(g=>`<div class="row2" data-id="${esc(g.id)}"><div><input class="inp" data-rn value="${esc(g.name)}" aria-label="Group name" style="height:30px;font-weight:600"><span class="k">${g.els.length} elements · saved on a ${(FR[g.frame]?.[2]||'').toLowerCase()} screen</span></div><button class="b" data-here>Add here</button><button class="b" data-all>Add to every screen</button><button class="b icon danger" data-del aria-label="Delete group">${I('trash',14)}</button></div>`).join(''):'<p style="color:var(--muted);margin:0">No groups yet.</p>'};draw();
 m.addEventListener('change',ev=>{const i=ev.target.closest('[data-rn]');const g=i&&groups.find(x=>x.id===i.closest('.row2').dataset.id);if(g&&i.value.trim()){const name=i.value.trim();putGroup({...g,name,updatedAt:Date.now()});P.screens.forEach(s=>s.els.forEach(e=>{if(e.lg===g.id)e.gn=name}));drawAll()}});
 m.addEventListener('click',ev=>{const row=ev.target.closest('.row2');if(!row)return;const id=row.dataset.id;if(ev.target.closest('[data-here]')){closeOverlay();insertGroup(id)}if(ev.target.closest('[data-all]')){closeOverlay();insertGroup(id,{all:true})}const dl=ev.target.closest('[data-del]');if(dl){if(dl.dataset.confirm){dropGroup(id);draw();toast('Group deleted')}else{dl.dataset.confirm='1';dl.innerHTML='Delete?';dl.classList.remove('icon');dl.style.width='auto';dl.style.padding='0 10px'}}})}
let gd=null;
$('#gbar').addEventListener('pointerdown',ev=>{const c=ev.target.closest('.gchip');if(!c||ev.button!==0)return;hidePrev();showPrev.cur=null;gd={id:c.dataset.grp,sx:ev.clientX,sy:ev.clientY,all:ev.shiftKey,g:null};c.setPointerCapture(ev.pointerId)});
$('#gbar').addEventListener('pointermove',ev=>{if(!gd)return;if(!gd.g&&Math.hypot(ev.clientX-gd.sx,ev.clientY-gd.sy)>5){const gr=groups.find(x=>x.id===gd.id),b=groupBox(gr);gd.g=dragGhost(groupInner(b),b.w,b.h,gr.name)}if(gd.g){gd.g.style.left=ev.clientX+'px';gd.g.style.top=ev.clientY+'px'}});
$('#gbar').addEventListener('pointerup',ev=>{if(!gd)return;const d=gd;gd=null;if(!d.g)return insertGroup(d.id,{all:d.all});d.g.remove();const r=$('#frame').getBoundingClientRect();if(!flowOn&&ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom)insertGroup(d.id,{cx:(ev.clientX-r.left)/scale,cy:(ev.clientY-r.top)/scale})});
$('#gbar').addEventListener('pointercancel',()=>{gd?.g?.remove();gd=null});
$('#gbar').addEventListener('click',ev=>{if(ev.target.closest('#gSave'))saveSelAsGroup();if(ev.target.closest('#gMan'))manageGroups()});
$('#gbar').addEventListener('pointerover',ev=>{if(ev.pointerType!=='mouse'||gd)return;const c=ev.target.closest('.gchip');if(c===showPrev.cur)return;showPrev.cur=c;hidePrev();if(!c)return;hidePrev.t=setTimeout(()=>{const gr=groups.find(x=>x.id===c.dataset.grp);if(!gr)return;const b=groupBox(gr);const p=document.createElement('div');p.className='pprev';p.id='pprev';p.innerHTML=`<div class="stage">${fitSpec(groupInner(b),b.w,b.h,300,180)}</div><div class="pm"><b>${esc(gr.name)}</b><span class="k">${gr.els.length} elements</span><p class="aka">${esc([...new Set(gr.els.map(e=>EM[e.type]?.n).filter(Boolean))].join(' · '))}</p></div><div class="pfoot">Click to add here · Shift-click for every screen · drag to place</div>`;document.body.appendChild(p);const r=c.getBoundingClientRect();p.style.left=Math.max(8,Math.min(innerWidth-p.offsetWidth-8,r.left))+'px';p.style.top=r.bottom+6+'px'},250)});
$('#gbar').addEventListener('pointerleave',()=>{if(!gd){showPrev.cur=null;hidePrev()}});

/* ---------- export ---------- */
function region(e,fw,fh){const cx=e.x+e.w/2,cy=e.y+e.h/2;const hz=e.w>=fw*.9?'full width':cx<fw/3?'left':cx>fw*2/3?'right':'center';const vt=cy<fh/3?'top':cy>fh*2/3?'bottom':'middle';return `${vt}, ${hz}`}
function describeScreen(s,head){const [fw,fh]=frameSize(s);const els=[...s.els].sort((a,b)=>(a.y-b.y)||(a.x-b.x));const lay=LAYOUTS.find(l=>l.id===s.layout);const gs=(s.guides||[]).filter(g=>!g.col);let t=`${head}\nFrame: ${FR[s.frame][2]}, ${fw}×${fh}px (coordinates are px from the top-left corner)\n`;if(s.notes)t+=`Purpose: ${s.notes}\n`;if(P.style?.s||okHex(P.style?.a))t+=`Visual style: ${styName(P.style).n}, ${styName(P.style).d}${okHex(P.style?.a)?`; accent colour ${P.style.a}`:''}\n`;if(gs.length)t+=`Layout${lay?` (${lay.n})`:''}: ${gs.map(g=>`${g.label} x ${g.x}–${g.x+g.w}, y ${g.y}–${g.y+g.h}`).join(' · ')}\n`;else if(lay)t+=`Layout: ${lay.n}\n`;t+=`\nElements, top to bottom then left to right:\n`;
 const out=els.map((e,i)=>{const d=EM[e.type],pn=panelOf(e,s),to=e.link&&scrName(e.link);t+=`\n${i+1}. ${d.n} [${d.id}]${e.t?` — "${e.t}"`:''}\n   at x ${e.x}, y ${e.y} · ${e.w}×${e.h}px · ${pn?`in ${pn}`:region(e,fw,fh)}\n`;if(e.note)t+=`   note: ${e.note}\n`;if(to)t+=e.link==='@back'?'   when clicked: goes back to the previous screen\n':`   when clicked: opens screen "${to}"\n`;return {type:e.type,name:d.n,label:e.t,x:e.x,y:e.y,w:e.w,h:e.h,...(pn?{panel:pn}:{}),...(e.note?{note:e.note}:{}),...(to?{goesTo:e.link==='@back'?'(back)':to}:{})}});
 return {text:t,data:{name:s.name,frame:{type:s.frame,width:fw,height:fh},purpose:s.notes||'',...(gs.length?{layout:gs.map(({label,x,y,w,h})=>({label,x,y,w,h}))}:{}),elements:out}}}
function flowList(){const out=[];P.screens.forEach(s=>s.els.forEach(e=>{const to=e.link==='@back'?'(back to the previous screen)':e.link&&scrName(e.link);if(to)out.push({from:s.name,element:elName(e).replace(/[“”]/g,'"'),to})}));return out}
function describe(...a){return withCustoms(describeBase(...a),a[0]?P.screens:[M])}
function withCustoms(r,screens){const used=usedCustoms(screens).map(c=>EM[c.id]).filter(Boolean);if(!used.length)return r;
 const text=r.text+`

YOUR ELEMENTS (added by the user; not in the standard library):
`+used.map(e=>`- ${e.n} [${e.id}]${e.d?`: ${e.d}`:''}${e.u?` Use: ${e.u}`:''}${e.aka.length?` Also called: ${e.aka.join(', ')}.`:''}${e.x.length?` Related to: ${e.x.join(', ')}.`:''}`).join('\n');
 let json=r.json;try{const j=JSON.parse(r.json);j.customElements=used.map(e=>({code:e.id,name:e.n,...(e.d?{description:e.d}:{}),...(e.u?{whenToUse:e.u}:{}),...(e.aka.length?{alsoCalled:e.aka}:{}),...(e.x.length?{relatedTo:e.x}:{})}));json=JSON.stringify(j,null,1)}catch{}return {...r,text,json}}
function describeBase(all){if(!all||P.screens.length===1){const r=describeScreen(M,`MOCKUP: "${P.name}"${P.screens.length>1||M.name!=='Screen 1'?` — screen "${M.name}"`:''}`);return {text:r.text,json:JSON.stringify(r.data,null,1)}}
 const fl=flowList();let t=`MOCKUP: "${P.name}" — ${P.screens.length} screens\nScreens: ${P.screens.map((s,i)=>`${i+1}. ${s.name}`).join(' · ')}\n`;if(fl.length)t+=`\nFLOW (what each link opens):\n`+fl.map(f=>`- ${f.from} › ${f.element} → ${f.to}`).join('\n')+'\n';const parts=P.screens.map((s,i)=>describeScreen(s,`SCREEN ${i+1} of ${P.screens.length}: "${s.name}"`));t+=parts.map(p=>`\n${'='.repeat(48)}\n${p.text}`).join('');return {text:t,json:JSON.stringify({name:P.name,screens:parts.map(p=>p.data),flow:fl},null,1)}}
$('#exportBtn').onclick=()=>{const hasBase=P.screens.some(x=>x.base),opts=[...(hasBase?[['changes','Changes only']]:[]),...(P.screens.length>1?[['all',`All ${P.screens.length} screens + flow`]]:[]),...(hasBase||P.screens.length>1?[['one',`Only “${esc(short(M.name,24))}”`]]:[])];let scope=opts[0]?.[0]||'one';
 const lead=()=>scope==='changes'?'Lists only what you changed on imported pages, so Claude updates the existing page instead of rebuilding it. New pages are described in full.':`Paste this into a chat with Claude. It names every element by its library code, where it sits and your notes${P.screens.length>1?', plus how the screens link together':''}.${db?' Saving also lets Claude read it straight from this page.':''}`;
 const m=showModal('Copy for Claude',`<p class="mlead" id="expLead"></p>${opts.length>1?`<div class="seg" id="expScope" role="group" aria-label="What to copy">${opts.map(([k,l])=>`<button data-s="${k}">${l}</button>`).join('')}</div>`:''}<textarea class="inp" id="expTxt" readonly style="min-height:300px;font:12px/1.5 var(--f-mono)"></textarea><div class="btnrow"><button class="b pri" id="cpAll">${I('copy',14)}Copy description + JSON</button><button class="b" id="cpTxt">Copy description only</button><button class="b" id="cpJson">Copy JSON only</button></div>`);let r;
 const fill=()=>{const d=scope==='changes'?describeDelta():describe(scope==='all');r={...d,full:`${d.text}\nJSON:\n${d.json}`};$('#expTxt').value=r.full;$('#expLead').textContent=lead();m.querySelectorAll('#expScope button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.s===scope))};fill();
 m.querySelector('#expScope')?.addEventListener('click',ev=>{const b=ev.target.closest('[data-s]');if(b){scope=b.dataset.s;fill()}});$('#cpAll').onclick=()=>copyText(r.full,'Copied. Paste it into Claude.',$('#expTxt'));$('#cpTxt').onclick=()=>copyText(r.text,'Description copied',$('#expTxt'));$('#cpJson').onclick=()=>copyText(r.json,'JSON copied',$('#expTxt'))};
function showModal(title,body,cls=''){closeOverlay();const m=document.createElement('div');m.className='modal';m.id='ovl';m.innerHTML=`<div class="mbox ${cls}" role="dialog" aria-label="${title}"><div class="mhead"><h3>${title}</h3><button class="b icon" data-close aria-label="Close">${I('x',16)}</button></div><div class="mbody">${body}</div></div>`;m.addEventListener('click',ev=>{if(ev.target===m||ev.target.closest('[data-close]'))closeOverlay()});document.body.appendChild(m);return m}
addEventListener('keydown',ev=>{if(ev.key==='Escape'&&document.getElementById('ovl'))closeOverlay()});

/* ---------- saving (shared db when available, this browser otherwise) ---------- */
let db=null,savedList=[];
const localSaved=()=>LS.get('uifg.saved',[]);
function refreshLocal(){if(!db)savedList=localSaved().sort((a,b)=>b.updatedAt-a.updatedAt)}
refreshLocal();
try{window.claude?.use?.('db').then(d=>{if(!d)return;db=d;db.collection('groups').orderBy('updatedAt','desc').onSnapshot(s=>{groups=s.docs.map(x=>({id:x.id,...x.data()}));drawGroupsBar()},()=>{});
  let firstEl=true;db.collection('elements').onSnapshot(s=>{const remote=s.docs.map(x=>({id:x.id,...x.data()}));if(firstEl){firstEl=false;custom.filter(c=>!remote.some(r=>r.id===c.id)).forEach(c=>{const {id,...doc}=c;db.doc('elements/'+id).set(doc).catch(()=>{})})}
   remote.forEach(r=>{const i=custom.findIndex(x=>x.id===r.id);if(i<0||(custom[i].updatedAt||0)<(r.updatedAt||0)){if(regCustom(r))i<0?custom.push(r):custom[i]=r}});LS.set('uifg.custom',custom);customsChanged()},()=>{});db.collection('mockups').orderBy('updatedAt','desc').onSnapshot(s=>{savedList=s.docs.map(x=>({id:x.id,...x.data()}));if(document.getElementById('savedList'))drawSaved()},()=>{})}).catch(()=>{})}catch{}
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'mockup';
const docCount=s=>(s.screens||[s]).reduce((a,x)=>a+(x.els||[]).length,0);
function projectDoc(){return {name:P.name,style:P.style||null,screens:P.screens.map(s=>({...s,els:s.els.map(({uid,...r})=>r)})),cur:P.cur,elements:usedCustoms(P.screens),summary:describe(true).text,updatedAt:Date.now()}}
async function persist(){const id=P.id,doc=projectDoc();P.example=false;P.savedSig=sig();saveDraft();if(db){try{await db.doc('mockups/'+id).set(doc);toast(`Saved “${P.name}”. Claude can read it from here.`)}catch(err){toast(err?.code==='quota_exceeded'?'Storage is full. Delete an old mockup and try again.':'Could not save to the shared store. Saved in this browser instead.');saveLocal(id,doc)}}else{if(saveLocal(id,doc))toast(`Saved “${P.name}” in this browser`);else{P.savedSig=null;drawStatus();toast('Couldn’t save: this browser’s storage is full. Download a backup, then delete old mockups.')}}}
function saveLocal(id,doc){const l=localSaved().filter(x=>x.id!==id);l.push({id,...doc});const ok=LS.set('uifg.saved',l);refreshLocal();drawStoreBar();return ok}
// Save overwrites the open mockup; Save as (or a first save) asks for a name and makes a new one.
function saveProject(asNew){if(P.id&&!asNew)return persist();const def=P.example?P.name.replace(/^Example: /,'My '):asNew&&P.id?`${P.name} copy`:P.name;showModal(asNew&&P.id?'Save as a new mockup':'Save mockup',`<p class="mlead">${asNew&&P.id?`Makes a separate copy. “${esc(P.name)}” stays as it was last saved.`:'Give it a name you will recognise later.'}</p><div class="fld"><label for="svName">Name</label><input class="inp" id="svName" value="${esc(def)}"></div><div class="btnrow"><button class="b pri" id="svGo">${I('save',14)}Save</button><button class="b" data-close>Cancel</button></div>`);const go=()=>{const n=$('#svName').value.trim()||'Untitled mockup';P.name=n;P.id=slug(n)+'-'+uid().slice(0,4);closeOverlay();persist();drawAll()};$('#svGo').onclick=go;$('#svName').onkeydown=ev=>{if(ev.key==='Enter')go()};setTimeout(()=>{$('#svName')?.focus();$('#svName')?.select()},0)}
$('#saveBtn').onclick=()=>saveProject(false);
// phones: the file actions live in one menu
$('#fileBtn').onclick=()=>{const m=showModal('File',`<div class="filemenu">${[['newBtn','plus','New mockup'],['openBtn','folder','Open…'],['saveBtn','save','Save'],['saveAsBtn','copy','Save as…'],['dlBtn','download','Download…']].map(([id,ic,l])=>`<button class="b" data-fm="${id}">${I(ic,16)}${l}</button>`).join('')}</div>`);m.addEventListener('click',ev=>{const b=ev.target.closest('[data-fm]');if(b){closeOverlay();$('#'+b.dataset.fm).click()}})};$('#saveAsBtn').onclick=()=>saveProject(true);
function saveBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
const saveJSON=(doc,name)=>{saveBlob(new Blob([JSON.stringify(doc,null,1)],{type:'application/json'}),name);toast('Downloaded '+name)};
// The file carries the groups it uses, so linked copies keep working in another browser
function downloadProject(){const doc={app:'ui-field-guide',version:2,...projectDoc(),groups:groups.filter(g=>P.screens.some(s=>s.els.some(e=>e.lg===g.id)))};if(!doc.elements.length)delete doc.elements;delete doc.summary;saveJSON(doc,slug(P.name)+'.json')}
async function downloadBackup(){refreshLocal();const doc={app:'ui-field-guide',kind:'backup',version:2,exportedAt:Date.now(),current:JSON.parse(JSON.stringify(P)),mockups:savedList,groups,elements:custom};saveJSON(doc,`ui-field-guide-backup-${new Date().toISOString().slice(0,10)}.json`);LS.set('uifg.lastBackup',Date.now());drawStoreBar()}
function showRestore(d){const ms=d.mockups||[],gs=d.groups||[];const pl=(n,w)=>`${n} ${w}${n===1?'':'s'}`;showModal('Restore a backup',`<p class="mlead">Backup from ${new Date(d.exportedAt).toLocaleString()}: ${pl(ms.length,'saved mockup')} and ${pl(gs.length,'group')}${d.current?`, plus the mockup that was open (“${esc(d.current.name)}”)`:''}. Restoring adds them to ${db?'this page':'this browser'}. Where something is already here, the newer version is kept.</p><div class="btnrow"><button class="b pri" id="rsGo">Restore</button>${d.current?`<button class="b" id="rsOpen">Restore and open “${esc(short(d.current.name,24))}”</button>`:''}<button class="b" data-close>Cancel</button></div>`);
 const go=async open=>{let a=0,b=0;for(const s of ms){const have=savedList.find(x=>x.id===s.id);if(have&&have.updatedAt>=s.updatedAt)continue;const {id,...doc}=s;if(db){try{await db.doc('mockups/'+id).set(doc)}catch{saveLocal(id,doc)}}else saveLocal(id,doc);a++}for(const g of gs){const have=groups.find(x=>x.id===g.id);if(have&&(have.updatedAt||0)>=(g.updatedAt||0))continue;await putGroup(g);b++}closeOverlay();if(open){pushUndo();loadProject(d.current);clearSel();pullLinked();setFlow(false)}else{pullLinked();drawAll()}toast(`Restored ${pl(a,'mockup')} and ${pl(b,'group')}${open?`, and opened “${P.name}”`:''}`)};
 $('#rsGo').onclick=()=>go(false);$('#rsOpen')&&($('#rsOpen').onclick=()=>go(true))}
/* images: draw the mockup's own HTML into a canvas through an SVG foreignObject, with the page fonts embedded */
let fontCSS=null;
async function embedFonts(){if(fontCSS!=null)return fontCSS;fontCSS='';try{const href=document.querySelector('link[rel=stylesheet][href*="fonts.googleapis"]').href;const css=await (await fetch(href)).text();const out=[];for(const b of css.split('/* ').filter(b=>b.startsWith('latin */'))){const face=b.slice(b.indexOf('@font-face'));const url=face.match(/url\((https:[^)]+)\)/)?.[1];if(!url)continue;const blob=await (await fetch(url)).blob();out.push(face.replace(url,await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(blob)})))}fontCSS=out.join('\n')}catch{}return fontCSS}
async function htmlImage(html,w,h,k=2){const css=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n')+'\n'+await embedFonts();const host=document.createElement('div');host.innerHTML=html;const th=document.documentElement.getAttribute('data-theme');k=Math.min(k,16000/w,16000/h);
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"${th?` data-theme="${th}"`:''}><foreignObject x="0" y="0" width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml" style="width:${w}px;height:${h}px;position:relative;background:var(--bg);color:var(--ink);font:14px/1.5 var(--f-body)"><style><![CDATA[${css}]]></style>${new XMLSerializer().serializeToString(host)}</div></foreignObject></svg>`;
 const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)});const c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);const x=c.getContext('2d');x.scale(k,k);x.drawImage(img,0,0);
 try{const png=await new Promise(r=>c.toBlob(r,'image/png'));if(png)return {blob:png,ext:'png'}}catch{}return {blob:new Blob([svg],{type:'image/svg+xml'}),ext:'svg'}}
const screenHTML=(s,[fw,fh]=frameSize(s))=>`<div class="xscreen${styCls(P.style)}" style="${styVars(P.style)}position:relative;width:${fw}px;height:${fh}px;background:var(--w-canvas,var(--surface));overflow:hidden">${s.els.map((e,i)=>`<div style="position:absolute;left:${e.x}px;top:${e.y}px;width:${e.w}px;height:${e.h}px;z-index:${i+1}">${render(e.type,e.t)}</div>`).join('')}</div>`;
// All screens on one sheet, four to a row, each with its name above it
function sheetHTML(){const pad=48,gap=48,head=40;let x=pad,y=pad,rowH=0,W=0,parts=[];P.screens.forEach((s,i)=>{const [fw,fh]=frameSize(s);if(i&&i%4===0){x=pad;y+=rowH+gap;rowH=0}parts.push(`<div style="position:absolute;left:${x}px;top:${y}px"><div style="font:600 20px/1 var(--f-display);height:${head}px">${esc(s.name)} <span style="font:500 13px var(--f-mono);color:var(--muted)">${FR[s.frame][2]}</span></div><div style="box-shadow:0 0 0 1px var(--line),var(--shadow);border-radius:6px;overflow:hidden">${screenHTML(s)}</div></div>`);x+=fw+gap;W=Math.max(W,x);rowH=Math.max(rowH,fh+head)});return {html:parts.join(''),w:W-gap+pad,h:y+rowH+pad}}
async function exportImage(kind){toast('Preparing image…');let html,w,h,name;
 if(kind==='screen'){[w,h]=frameSize(M);html=screenHTML(M);name=`${P.name} - ${M.name}`}
 else if(kind==='all'){({html,w,h}=sheetHTML());name=`${P.name} - all screens`}
 else{const was=flowOn,wc=conOn;conOn=false;if(!flowOn)setFlow(true);else drawFlow();const fc=$('.flowc');w=fc.offsetWidth;h=fc.offsetHeight;html=fc.outerHTML.replace('class="flowc"','class="flowc" style="position:absolute;left:0;top:0"');conOn=wc;was?drawFlow():setFlow(false);name=`${P.name} - flow map`}
 try{const r=await htmlImage(html,w,h);saveBlob(r.blob,`${slug(name)}.${r.ext}`);toast(r.ext==='png'?`Downloaded ${slug(name)}.png`:'This browser blocked PNG export, so it saved an SVG image instead.')}catch(err){toast('Could not make the image in this browser.')}}
function openDownloads(){const last=LS.get('uifg.lastBackup',0);refreshLocal();showModal('Download',`<div class="dlsec"><h4>Images</h4><div class="btnrow"><button class="b" data-img="screen">${I('image',14)}This screen</button>${P.screens.length>1?`<button class="b" data-img="all">${I('image',14)}All ${P.screens.length} screens</button>`:''}<button class="b" data-img="flow">${I('flow',14)}Flow map</button></div><p class="mlead">Sharp PNGs (2×) of the mockup as it looks, without selection handles or guides.</p></div><div class="dlsec"><h4>This mockup</h4><div class="btnrow"><button class="b" data-dl="file">${I('download',14)}Mockup file (.json)</button></div><p class="mlead">Open it again in any browser from Open → Open a file. Includes the groups it uses.</p></div><div class="dlsec"><h4>Backup</h4><div class="btnrow"><button class="b pri" data-dl="backup">${I('download',14)}Download a full backup</button></div><p class="mlead">${db?'Saved mockups on this page':`All ${savedList.length} saved mockups in this browser`}, your ${groups.length} group${groups.length===1?'':'s'} and the mockup that’s open now, in one file. Keep it somewhere safe in case browser storage is cleared. Restore it from Open → Open a file. <b>Last backup: ${last?new Date(last).toLocaleString():'never'}</b>. This browser holds ${mb(storeUsed())} of about ${mb(STORE_LIMIT)}.</p></div>`).addEventListener('click',ev=>{const im=ev.target.closest('[data-img]');if(im){closeOverlay();exportImage(im.dataset.img)}const d=ev.target.closest('[data-dl]');if(d){d.dataset.dl==='file'?downloadProject():downloadBackup();closeOverlay()}})}
$('#dlBtn').innerHTML=I('download',14)+'Download';$('#dlBtn').onclick=openDownloads;
function drawSaved(){const host=document.getElementById('savedList');if(!host)return;host.innerHTML=savedList.length?savedList.map(s=>{const n=s.screens?.length||1;return `<div class="row2" data-id="${esc(s.id)}"><div><b>${esc(s.name)}${s.id===P.id?' <span class="k">open now</span>':''}</b><span class="k">${n} screen${n>1?'s':''} · ${docCount(s)} elements · ${new Date(s.updatedAt).toLocaleString()}</span></div><button class="b" data-open>Open</button><button class="b" data-from title="Open a copy, so the original stays untouched. Save then asks for a new name.">Start from</button><button class="b icon danger" data-del aria-label="Delete">${I('trash',14)}</button></div>`}).join(''):'<p style="color:var(--muted);margin:0">No saved mockups yet. Press Save in the toolbar to keep one here.</p>'}
$('#openBtn').onclick=()=>{refreshLocal();const m=showModal('Open a mockup',`<p class="mlead">${db?'Saved to this page. Tell Claude a mockup’s name and it can read it directly.':'Saved in this browser. Use Download to back everything up or move a mockup to another browser.'} <b>Start from</b> opens a copy, so you can build on an old mockup without changing it.</p><div class="btnrow"><button class="b" id="opNew">${I('plus',14)}New blank mockup</button><button class="b" id="opWeb">${I('globe',14)}Import a web page…</button><button class="b" id="opImp">${I('upload',14)}Open a file…</button><input type="file" id="opFile" accept=".json,application/json" hidden></div><div class="saved" id="savedList"></div>`);drawSaved();
 m.addEventListener('click',async ev=>{if(ev.target.closest('#opNew')){closeOverlay();return newProject()}if(ev.target.closest('#opWeb')){closeOverlay();return openImportHelp()}if(ev.target.closest('#opImp'))return $('#opFile').click();const row=ev.target.closest('.row2');if(!row)return;const s=savedList.find(x=>x.id===row.dataset.id);if(!s)return;
  if(ev.target.closest('[data-open]')){pushUndo();loadProject(s);pullLinked();P.savedSig=sig();clearSel();closeOverlay();setFlow(false);toast(`Opened “${s.name}”`)}
  if(ev.target.closest('[data-from]')){pushUndo();loadProject({...s,id:null,name:`${s.name} copy`});clearSel();closeOverlay();setFlow(false);toast(`Started from “${s.name}”. Save keeps this as a new mockup.`)}
  const dl=ev.target.closest('[data-del]');if(dl){if(dl.dataset.confirm){if(db){try{await db.doc('mockups/'+s.id).delete()}catch{toast('Could not delete')}}else{LS.set('uifg.saved',localSaved().filter(x=>x.id!==s.id));refreshLocal();drawSaved();drawStoreBar()}if(P.id===s.id){P.id=null;drawStatus()}toast('Deleted')}else{dl.dataset.confirm='1';dl.innerHTML='Delete?';dl.classList.remove('icon');dl.style.width='auto';dl.style.padding='0 10px'}}});
 $('#opFile').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(d.kind==='elements'){closeOverlay();const n=importDefs(d.elements);return toast(n?`Added or updated ${n} element${n>1?'s':''} in Your elements`:'Nothing new in that library file')}importDefs(d.elements);if(d.kind==='backup'){closeOverlay();return showRestore(d)}if(d.kind==='capture'){closeOverlay();return receiveCapture(d)}if(!d.screens&&!d.els)throw 0;for(const g of d.groups||[])if(!groups.some(x=>x.id===g.id))await putGroup(g);pushUndo();loadProject({...d,id:null,example:false});clearSel();pullLinked();closeOverlay();setFlow(false);toast(`Opened “${P.name}” from the file. Save keeps it here.`)}catch{toast('That file is not a UI Field Guide mockup')}}};
